#### 415\. 字符串相加
(https://leetcode.cn/problems/add-strings)
```cpp
class Solution {
  public:
	string addStrings(string num1, string num2) {
		int maxLen = max(num1.size(), num2.size());
		if(num1.size() == num2.size()) {
			num1.insert(0, "0");
			num2.insert(0, "0");
		}
		if(num1.size() > num2.size()) {
			num2.insert(0, string(maxLen - num2.size() + 1, '0'));
			num1.insert(0, "0");
		}
		if(num1.size() < num2.size()) {
			num1.insert(0, string(maxLen - num1.size() + 1, '0'));
			num2.insert(0, "0");
		}
		int	   add = 0, jump = 0;
		string result;
		for(int i = maxLen; i >= 0; i--) {
			add = num1[i] + num2[i] - 96 + jump;
			result.push_back(static_cast<char>('0' + add % 10));
			jump = 0;
			if(add > 9) {
				jump = 1;
			}
		}
		if(result.back() == '0') {
			result.pop_back();
		}
		reverse(result.begin(), result.end());
		return result;
	}
};
```
题目比较简单，但是坑很多:
- 相等比较要放在大鱼和小于比较之前，否则大鱼小于比较完之后，两者一定相等会多塞给 num1 和 num2 一个 0
- 旋转之后要取出前导 0
- 如果不使用 `stoi/stoll` 等函数的话需要清楚转换方式，『0』的 ascii 序号为 4

